"use strict";(self.webpackChunk_open_lingua_ielts_mastery_hub_website=self.webpackChunk_open_lingua_ielts_mastery_hub_website||[]).push([["37"],{3120(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/2026/09/11/ielts-mastery-hub-reddit-r-ielts-launch","metadata":{"permalink":"/ielts-mastery-hub/blog/2026/09/11/ielts-mastery-hub-reddit-r-ielts-launch","source":"@site/blog/2026-09-11-ielts-mastery-hub-reddit-r-ielts-launch.mdx","title":"I built a free, open-source desktop app for IELTS practice (Reading, Listening & AI-graded Writing)","description":"A Reddit post for r/IELTS introducing IELTS Mastery Hub \u2014 a free, MIT-licensed desktop app with timed Reading and Listening practice, AI-graded Writing, and progress tracking for Windows, Linux, and macOS.","date":"2026-09-11T00:00:00.000Z","tags":[{"inline":true,"label":"ielts","permalink":"/ielts-mastery-hub/blog/tags/ielts"},{"inline":true,"label":"open-source","permalink":"/ielts-mastery-hub/blog/tags/open-source"},{"inline":true,"label":"reddit","permalink":"/ielts-mastery-hub/blog/tags/reddit"},{"inline":true,"label":"community","permalink":"/ielts-mastery-hub/blog/tags/community"},{"inline":true,"label":"study-tools","permalink":"/ielts-mastery-hub/blog/tags/study-tools"}],"readingTime":2.01,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"I built a free, open-source desktop app for IELTS practice (Reading, Listening & AI-graded Writing)","date":"2026-09-11T00:00:00.000Z","tags":["ielts","open-source","reddit","community","study-tools"],"description":"A Reddit post for r/IELTS introducing IELTS Mastery Hub \u2014 a free, MIT-licensed desktop app with timed Reading and Listening practice, AI-graded Writing, and progress tracking for Windows, Linux, and macOS."},"unlisted":false,"nextItem":{"title":"First Blog Post","permalink":"/ielts-mastery-hub/blog/first-blog-post"}},"content":"**I built a free, open-source desktop app for IELTS practice (Reading, Listening & AI-graded Writing)**\\n\\nHey everyone \u{1F44B}\\n\\nWhile prepping for IELTS I got frustrated that almost every decent practice tool is either behind a subscription, locked to a few free tests, or just doesn\'t look/feel like the actual exam. So I ended up building my own \u2014 and I\'m putting it out there free for anyone who wants it.\\n\\nIt\'s called **IELTS Mastery Hub**. It\'s a desktop app (Windows, Linux, macOS), completely free, and open source under the MIT license. No account, no paywall, no \\"upgrade to see your score.\\"\\n\\n**Quick demo video:** https://github.com/user-attachments/assets/0a68fb14-e7cd-4cd2-8774-1c6bc53cae0f\\n\\n**What\'s in it right now:**\\n\\n- \u{1F4D6} **Reading** \u2014 split-screen layout like the real thing, covering the official question types, with auto-scoring\\n- \u{1F3A7} **Listening** \u2014 audio sections with progressive difficulty\\n- \u270D\uFE0F **Writing** \u2014 dual-pane editor with AI feedback based on the official IELTS scoring criteria (Task Achievement, Coherence, Lexical Resource, Grammar)\\n- \u{1F4CA} **Dashboard** \u2014 tracks your scores over time so you can actually see if you\'re improving\\n\\nThe Writing feedback has honestly been the most useful part for me personally \u2014 getting *some* structured feedback on band criteria beats writing essays into the void while waiting for a tutor.\\n\\n**Install:**\\n\\nmacOS / Linux:\\n```\\ncurl -fsSL https://open-lingua.github.io/ielts-mastery-hub/install/install.sh | sh\\n```\\n\\nWindows (PowerShell):\\n```\\nirm https://open-lingua.github.io/ielts-mastery-hub/install/install.ps1 | iex\\n```\\n\\nOr build from source: `git clone https://github.com/open-lingua/ielts-mastery-hub.git`\\n\\nRepo: https://github.com/open-lingua/ielts-mastery-hub\\nDocs: https://open-lingua.github.io/ielts-mastery-hub/docs/intro/\\n\\n**Important disclaimer:** this is an independent, non-commercial educational project. It is **not affiliated with or endorsed by the British Council, IDP Education, or Cambridge Assessment English** \u2014 IELTS is a registered trademark of its respective owners. The practice content is AI-generated for study purposes, so treat it as practice material, not as official past papers. It won\'t be 100% accurate, and your real band score is decided by real examiners.\\n\\nI\'d really love feedback from people actually sitting the test \u2014 especially on whether the Reading/Listening timing and question formats feel close enough to the real exam, and whether the Writing feedback is actually helpful or just generic. If you find something wrong or missing, open an issue (or a PR, if that\'s your thing).\\n\\nHappy to answer questions in the comments. Good luck to everyone testing soon \u{1F340}"},{"id":"first-blog-post","metadata":{"permalink":"/ielts-mastery-hub/blog/first-blog-post","source":"@site/blog/2019-05-28-first-blog-post.mdx","title":"First Blog Post","description":"Lorem ipsum dolor sit amet...","date":"2019-05-28T00:00:00.000Z","tags":[{"inline":false,"label":"Hola","permalink":"/ielts-mastery-hub/blog/tags/hola","description":"Hola tag description"},{"inline":false,"label":"Docusaurus","permalink":"/ielts-mastery-hub/blog/tags/docusaurus","description":"Docusaurus tag description"}],"readingTime":0.13,"hasTruncateMarker":true,"authors":[{"name":"S\xe9bastien Lorber","title":"Docusaurus maintainer","url":"https://sebastienlorber.com","page":{"permalink":"/ielts-mastery-hub/blog/authors/all-sebastien-lorber-articles"},"socials":{"x":"https://x.com/sebastienlorber","linkedin":"https://www.linkedin.com/in/sebastienlorber/","github":"https://github.com/slorber","newsletter":"https://thisweekinreact.com"},"imageURL":"https://github.com/slorber.png","key":"slorber"},{"name":"Yangshun Tay","title":"Ex-Meta Staff Engineer, Co-founder GreatFrontEnd","url":"https://linkedin.com/in/yangshun","page":{"permalink":"/ielts-mastery-hub/blog/authors/yangshun"},"socials":{"x":"https://x.com/yangshunz","linkedin":"https://www.linkedin.com/in/yangshun/","github":"https://github.com/yangshun","newsletter":"https://www.greatfrontend.com"},"imageURL":"https://github.com/yangshun.png","key":"yangshun"}],"frontMatter":{"slug":"first-blog-post","title":"First Blog Post","authors":["slorber","yangshun"],"tags":["hola","docusaurus"]},"unlisted":false,"prevItem":{"title":"I built a free, open-source desktop app for IELTS practice (Reading, Listening & AI-graded Writing)","permalink":"/ielts-mastery-hub/blog/2026/09/11/ielts-mastery-hub-reddit-r-ielts-launch"}},"content":"Lorem ipsum dolor sit amet...\\n\\n{/* truncate */}\\n\\n...consectetur adipiscing elit. Pellentesque elementum dignissim ultricies. Fusce rhoncus ipsum tempor eros aliquam consequat. Lorem ipsum dolor sit amet"}]}}')}}]);